<?php
require __DIR__.'/app-bootstrap.php';
$admin=require_admin();
$flash=null;
function discount_date_value(string $value,bool $end=false):?string {
    $value=trim($value);
    if($value==='')return null;
    $d=DateTime::createFromFormat('Y-m-d',$value);
    if(!$d||$d->format('Y-m-d')!==$value)throw new RuntimeException('Enter valid dates.');
    return $value.($end?' 23:59:59':' 00:00:00');
}
function discount_form_values():array {
    $type=$_POST['discount_type']??'percent';if(!in_array($type,['percent','fixed'],true))throw new RuntimeException('Invalid discount type.');
    $kind=$_POST['promotion_kind']??'code';if(!in_array($kind,['code','launch','genre','bundle'],true))throw new RuntimeException('Invalid promotion type.');
    $code=discount_code_normalize((string)($_POST['code']??''));if(!preg_match('/^[A-Z0-9_-]{3,64}$/',$code))throw new RuntimeException('Code must be 3-64 characters using A-Z, 0-9, hyphens or underscores.');
    $value=(int)($_POST['discount_value']??0);if(($type==='percent'&&($value<1||$value>100))||($type==='fixed'&&$value<1))throw new RuntimeException('Enter a valid discount value.');
    $minimum=(float)str_replace(',','',(string)($_POST['minimum_subtotal']??'0'));if(!is_finite($minimum)||$minimum<0)throw new RuntimeException('Enter a valid minimum basket value.');
    $limit=trim((string)($_POST['usage_limit']??''));if($limit!==''&&((int)$limit<1||!ctype_digit($limit)))throw new RuntimeException('Usage limit must be a positive whole number.');
    $userId=(int)($_POST['user_id']??0);if($userId<1)$userId=null;$genreId=(int)($_POST['genre_id']??0);if($kind==='genre'&&$genreId<1)throw new RuntimeException('Choose a genre for a genre sale.');if($kind!=='genre')$genreId=null;
    $minimumItems=max(0,(int)($_POST['minimum_items']??0));if($kind==='bundle'&&$minimumItems<2)throw new RuntimeException('Bundle offers need at least two tracks.');
    return ['code'=>$code,'promotion_kind'=>$kind,'user_id'=>$userId,'genre_id'=>$genreId,'one_time_per_user'=>isset($_POST['one_time_per_user'])?1:0,'discount_type'=>$type,'discount_value'=>$value,'minimum_subtotal_pence'=>(int)round($minimum*100),'minimum_items'=>$minimumItems,'auto_apply'=>$kind==='code'?0:1,'starts_at'=>discount_date_value((string)($_POST['starts_at']??'')),'ends_at'=>discount_date_value((string)($_POST['ends_at']??''),true),'usage_limit'=>$limit===''?null:(int)$limit,'active'=>isset($_POST['active'])?1:0];
}if($_SERVER['REQUEST_METHOD']==='POST'){
    try{
        require_csrf();$action=(string)($_POST['action']??'');
        if($action==='discount_delete'){$id=(int)($_POST['id']??0);$pdo->prepare('DELETE FROM discount_codes WHERE id=?')->execute([$id]);$flash=['ok'=>true,'message'=>'Discount deleted.'];}
        elseif($action==='discount_toggle'){$id=(int)($_POST['id']??0);$pdo->prepare('UPDATE discount_codes SET active=1-active WHERE id=?')->execute([$id]);$flash=['ok'=>true,'message'=>'Discount status updated.'];}
        elseif($action==='discount_save'){
            $data=discount_form_values();$id=(int)($_POST['id']??0);
            if($id){$st=$pdo->prepare('SELECT id FROM discount_codes WHERE code=? AND id<>?');$st->execute([$data['code'],$id]);if($st->fetch())throw new RuntimeException('That code already exists.');$sql='UPDATE discount_codes SET code=?,promotion_kind=?,user_id=?,genre_id=?,one_time_per_user=?,discount_type=?,discount_value=?,minimum_subtotal_pence=?,minimum_items=?,auto_apply=?,starts_at=?,ends_at=?,usage_limit=?,active=? WHERE id=?';$pdo->prepare($sql)->execute([$data['code'],$data['promotion_kind'],$data['user_id'],$data['genre_id'],$data['one_time_per_user'],$data['discount_type'],$data['discount_value'],$data['minimum_subtotal_pence'],$data['minimum_items'],$data['auto_apply'],$data['starts_at'],$data['ends_at'],$data['usage_limit'],$data['active'],$id]);}
            else{$st=$pdo->prepare('SELECT id FROM discount_codes WHERE code=?');$st->execute([$data['code']]);if($st->fetch())throw new RuntimeException('That code already exists.');$sql='INSERT INTO discount_codes(code,promotion_kind,user_id,genre_id,one_time_per_user,discount_type,discount_value,minimum_subtotal_pence,minimum_items,auto_apply,starts_at,ends_at,usage_limit,active) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?)';$pdo->prepare($sql)->execute([$data['code'],$data['promotion_kind'],$data['user_id'],$data['genre_id'],$data['one_time_per_user'],$data['discount_type'],$data['discount_value'],$data['minimum_subtotal_pence'],$data['minimum_items'],$data['auto_apply'],$data['starts_at'],$data['ends_at'],$data['usage_limit'],$data['active']]);}
            $flash=['ok'=>true,'message'=>$id?'Discount updated.':'Discount created.'];
        }
    }catch(Throwable $e){$flash=['ok'=>false,'message'=>$e->getMessage()];}
}
$users=$pdo->query('SELECT id,display_name,email FROM users ORDER BY display_name,email')->fetchAll();$genres=$pdo->query('SELECT id,name FROM genres ORDER BY name')->fetchAll();
$codes=$pdo->query('SELECT d.*,u.display_name,u.email FROM discount_codes d LEFT JOIN users u ON u.id=d.user_id ORDER BY d.active DESC,d.created_at DESC,d.id DESC')->fetchAll();
layout_header('Discounts');
