ustomers</option><?php foreach($users as $user):?><option value="<?=$user['id']?>" <?=$code['user_id']==$user['id']?'selected':''?>><?=e($user['display_name'].' · '.$user['email'])?></option><?php endforeach;?></select></label><label class="check"><input type="checkbox" name="one_time_per_user" <?=$code['one_time_per_user']?'checked':''?>> One use per customer account</label><label class="check"><input type="checkbox" name="active" <?=$code['active']?'checked':''?>> Active</label><div class="form-actions wide"><button class="button">Save</button></div></form>
